package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Real SQLite/private fixture deletion only; no recording, playback, alarms or physical outputs. */
public class PrivacyHistoryFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private MainActivity activity;
    private UiObject2 object(String description)throws Exception{UiObject2 found=device.wait(Until.findObject(By.desc(description)),2000);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(description));found=device.wait(Until.findObject(By.desc(description)),5000);}assertNotNull(description,found);return found;}
    private void click(String text)throws Exception{UiObject2 found=device.wait(Until.findObject(By.text(text)),2000);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),5000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    private void positive(String text)throws Exception{String description=text.equals("Delete history")?"Confirm history deletion":"Confirm audio cleanup";UiObject2 button=device.wait(Until.findObject(By.desc(description)),5000);assertNotNull(text,button);assertEquals(text,button.getText());button.click();assertTrue("Confirmation action must be handled",device.wait(Until.gone(By.desc(description)),5000));i.waitForIdleSync();}
    private void keep()throws Exception{UiObject2 button=device.wait(Until.findObject(By.desc("Keep history")),5000);assertNotNull(button);assertEquals("Keep",button.getText());button.click();assertTrue("Keep must dismiss the confirmation",device.wait(Until.gone(By.desc("Keep history")),5000));i.waitForIdleSync();}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(MainActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,MainActivity.class).putExtra("destination",3).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(MainActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}click("Data & privacy");assertTrue("Actual Privacy route must replace Settings",device.wait(Until.hasObject(By.text("Your sleep data stays on this phone.")),5000));i.waitForIdleSync();}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(MainActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(MainActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Data & privacy")),5000));}
    private void capture(String suffix)throws Exception{UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));if(scroll.exists())scroll.scrollToEnd(4);long until=SystemClock.elapsedRealtime()+5000;CountDownLatch committed=new CountDownLatch(1);boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(committed::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused rendered privacy window",registered[0]);assertTrue(committed.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"privacy-history-"+suffix+".png")));}
    private HistoryEraseJobs.Job awaitInspection(Records.Factory factory)throws Exception{long until=SystemClock.elapsedRealtime()+5000;HistoryEraseJobs.Job job;while((job=HistoryErase.jobs.get(factory))==null&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(25);assertNotNull("Entering Privacy from resumed Settings must start inspection",job);assertEquals(HistoryEraseJobs.Kind.INSPECT,job.kind);return job;}
    private void await(Records.Factory factory)throws Exception{HistoryErase.drain(10000);HistoryEraseJobs.Job job=HistoryErase.jobs.get(factory);assertNotNull(job);assertTrue(job.done);}
    private Map<String,String> files(File root)throws Exception{Map<String,String> out=new TreeMap<>();if(!root.exists())return out;try(java.util.stream.Stream<java.nio.file.Path> paths=Files.walk(root.toPath())){for(java.nio.file.Path path:(Iterable<java.nio.file.Path>)paths::iterator)if(Files.isRegularFile(path))out.put(root.toPath().relativize(path).toString(),Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path))));}return out;}
    @Test public void confirmedEraseIsRetainedDbFirstAndPendingAudioRetriesWithoutDeletingNewHistory()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));
        Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());Map<String,String> originalFiles=files(c.getFilesDir());String name="privacy-history-"+UUID.randomUUID()+".db",prefix="privacy-history-"+UUID.randomUUID();Records.Factory previous=Records.factory;AtomicReference<CountDownLatch> gate=new AtomicReference<>();AtomicInteger workerOpens=new AtomicInteger();AtomicBoolean failWorker=new AtomicBoolean();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof MainActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        Records.Factory fixture=context->{if(Looper.myLooper()!=Looper.getMainLooper()){workerOpens.incrementAndGet();if(failWorker.getAndSet(false))throw new android.database.sqlite.SQLiteException("Fixture storage unavailable");CountDownLatch hold=gate.get();if(hold!=null)try{if(!hold.await(30,TimeUnit.SECONDS))throw new IllegalStateException("Fixture worker gate timed out");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}return new Store(context,name);};
        File wav=FileSafety.clip(c,prefix+".wav"),blocked=FileSafety.clip(c,prefix+"-blocked.wav"),child=new File(blocked,"owned-unlink-blocker");String original;
        try(Store store=new Store(c)){original=store.backup().toString();}
        try{
            assertTrue(wav.getParentFile().isDirectory()||wav.getParentFile().mkdirs());Files.write(wav.toPath(),new byte[]{82,73,70,70,4,0,0,0,87,65,86,69});assertTrue(blocked.mkdir());Files.write(child.toPath(),new byte[]{1});
            try(Store store=new Store(c,name)){Alarm a=new Alarm(730);a.enabled=false;a.label="Fixture alarm stays";store.save(a);long id=store.begin();store.end(id,false);store.annotate(id,"Fixture note",3);store.clip(id,System.currentTimeMillis(),wav.getName(),.5);store.clip(id,System.currentTimeMillis(),blocked.getName(),.5);}
            i.runOnMainSync(()->Records.factory=fixture);launch();awaitInspection(fixture);await(fixture);object("Delete sleep history").click();keep();try(Store store=new Store(c,name)){assertEquals(1,store.rows("SELECT id FROM sessions").size());}assertTrue(wav.exists());capture("ready");
            failWorker.set(true);object("Delete sleep history").click();positive("Delete history");await(fixture);recreate();object("Delete sleep history");assertEquals("Fixture storage unavailable",HistoryErase.jobs.get(fixture).error);assertFalse(HistoryErase.jobs.get(fixture).erased);capture("error");assertTrue(wav.exists());try(Store store=new Store(c,name)){assertEquals(1,store.rows("SELECT id FROM sessions").size());}
            CountDownLatch hold=new CountDownLatch(1);gate.set(hold);int before=workerOpens.get();object("Delete sleep history").click();positive("Delete history");assertFalse(object("Delete sleep history").isEnabled());recreate();assertFalse(object("Delete sleep history").isEnabled());capture("busy");assertEquals(before+1,workerOpens.get());
            // Finish the observer before the temporary factory change; a new UI binding must
            // legitimately use its own current factory, while the submitted worker stays pinned.
            MainActivity closing=activity;i.runOnMainSync(closing::finish);long closedBy=SystemClock.elapsedRealtime()+5000;boolean[] destroyed={false};while(!destroyed[0]&&SystemClock.elapsedRealtime()<closedBy){i.runOnMainSync(()->destroyed[0]=closing.isDestroyed());if(!destroyed[0])SystemClock.sleep(50);}assertTrue("Busy privacy observer must close independently of worker",destroyed[0]);
            i.runOnMainSync(()->Records.factory=context->{throw new AssertionError("Worker storage scope drifted");});hold.countDown();gate.set(null);await(fixture);i.runOnMainSync(()->Records.factory=fixture);launch();
            assertTrue(device.wait(Until.hasObject(By.desc("Retry audio cleanup")),5000));capture("pending");assertFalse(wav.exists());assertTrue(child.isFile());try(Store store=new Store(c,name)){assertTrue(store.rows("SELECT id FROM sessions").isEmpty());assertTrue(store.rows("SELECT id FROM clips").isEmpty());assertEquals(1,store.rows("SELECT clip FROM pending_clip_deletes").size());assertEquals("Fixture alarm stays",store.alarm(730).label);long fresh=store.begin();store.end(fresh,false);}
            assertTrue(child.delete());object("Retry audio cleanup").click();positive("Retry audio cleanup");await(fixture);recreate();assertTrue(device.wait(Until.hasObject(By.desc("Delete sleep history")),5000));capture("done");assertFalse(blocked.exists());try(Store store=new Store(c,name)){assertTrue(store.rows("SELECT clip FROM pending_clip_deletes").isEmpty());assertEquals(1,store.rows("SELECT id FROM sessions").size());assertEquals("Fixture alarm stays",store.alarm(730).label);}
            // Another record editor may add a pending journal row after this binding completed.
            try(Store store=new Store(c,name)){ContentValues pending=new ContentValues();pending.put("clip",990000);pending.put("session",1);pending.put("path",prefix+"-later.wav");pending.put("time",System.currentTimeMillis());store.getWritableDatabase().insertOrThrow("pending_clip_deletes",null,pending);}
            HistoryEraseJobs.Job beforeReentry=HistoryErase.jobs.get(fixture);
            object("Back").click();
            assertTrue("Back must leave the actual Privacy route",device.wait(Until.gone(By.text("Your sleep data stays on this phone.")),5000));
            click("Data & privacy");
            assertTrue("Reentry must show the actual Privacy route",device.wait(Until.hasObject(By.text("Your sleep data stays on this phone.")),5000));
            long inspectionBy=SystemClock.elapsedRealtime()+5000;
            while(HistoryErase.jobs.get(fixture)==beforeReentry&&SystemClock.elapsedRealtime()<inspectionBy)SystemClock.sleep(25);
            HistoryEraseJobs.Job refreshed=HistoryErase.jobs.get(fixture);
            assertNotSame("Reentry must request a new inspection, not reuse a completed count",beforeReentry,refreshed);
            assertNotNull("Reentry inspection exists for the pinned fixture",refreshed);
            assertEquals("Reentry uses inspection only",HistoryEraseJobs.Kind.INSPECT,refreshed.kind);
            await(fixture);
            assertEquals("Reentry discovers the later journal without deleting the new night",1,HistoryErase.jobs.get(fixture).pending);
            UiObject2 retry=object("Retry audio cleanup");
            assertTrue("The refreshed cleanup action is visible",retry.getVisibleBounds().height()>0);
            retry.click();positive("Retry audio cleanup");await(fixture);
            try(Store store=new Store(c,name)){assertTrue("Retry clears the later unlink journal",store.rows("SELECT clip FROM pending_clip_deletes").isEmpty());assertEquals("Retry preserves the new recorded night",1,store.rows("SELECT id FROM sessions").size());}
            assertEquals(prefs,Prefs.of(c).getAll());try(Store store=new Store(c)){assertEquals(original,store.backup().toString());}assertEquals(originalFiles,files(c.getFilesDir()));assertFalse(AlarmService.active);assertFalse(TrackingService.running);
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"privacy-history-failure.png"));device.dumpWindowHierarchy(new File(folder,"privacy-history-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{CountDownLatch hold=gate.getAndSet(null);if(hold!=null)hold.countDown();try{HistoryErase.drain(15000);i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));HistoryErase.jobs.forget(fixture);}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->Records.factory=previous);if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(name);Files.deleteIfExists(wav.toPath());Files.deleteIfExists(child.toPath());Files.deleteIfExists(blocked.toPath());}}
    }
}
